export const ages=[{id:'primary',name:'Story World',range:'Under 10',verb:'Watch. Play. Discover.',desc:'Big ideas, little adventures. See every concept come to life.',icon:'✦'},{id:'middle',name:'Discovery Lab',range:'Ages 10–12',verb:'Wonder. Test. Discover.',desc:'Follow your curiosity through experiments and missions.',icon:'◈'},{id:'secondary',name:'Challenge Studio',range:'Ages 13–14',verb:'Understand. Build. Solve.',desc:'Tackle real problems with code, models, and projects.',icon:'⌘'},{id:'advanced',name:'Research Workspace',range:'Ages 15–20+',verb:'Model. Analyze. Innovate.',desc:'Connect rigorous theory to practical investigation.',icon:'⌁'}];
